mapper.select:
SELECT * FROM ( SELECT A.*, ROWNUM RNUM FROM ( SELECT * FROM ( SELECT M.MBR_CD M_MBR_CD , M.MBR_ID , M.MBR_PW , M.MBR_NM , M.MBR_NNM , M.MBR_TELNO , M.MBR_EML_ADDR , M.MBR_BASIC_ADDR , M.MBR_DETAIL_ADDR , M.MBR_PROFIL_IMAGE , M.MBR_FRST_REG_DT , M.MBR_STATUS_CODE , M.MBR_DELETE_DATE , M.MBR_ZIP , B.MBR_CD B_MBR_CD , B.BROK_NM , B.BROK_REG_NO , B.CRTF_NO , B.REPR_NM , B.REPR_TEL_NO , B.REG_DTM , B.BROK_ADDR2 , B.BROK_ADDR1 , B.BROK_ZIP , B.AUTH_APPR_YN B_AUTH_APPR_YN , B.AUTH_APPR_DT B_AUTH_APPR_DT , NULL AS RENTAL_PTY_ID , NULL AS RENTAL_PTY_BIZ_REG_FILE_PATH , NULL AS RENTAL_PTY_REG_BLDG_CNT , NULL AS RENTAL_PTY_BIZ_REG_NO , NULL AS RENTAL_PTY_FILE , NULL AS RENTAL_PTY_FILE2 , NULL AS LSR_YN_TYPE_CD , NULL AS T_MBR_CD , NULL AS LSR_TYPE_GROUP_CD , NULL AS T_AUTH_APPR_YN , NULL AS T_AUTH_APPR_DT , F_B.FILE_ID AS B_FILE_ID , NULL AS T_FILE_ID FROM MEMBER M INNER JOIN BROKER B ON M.MBR_CD = B.MBR_CD LEFT OUTER JOIN FILES F_B ON F_B.FILE_SOURCE_REF = 'BROKER' AND F_B.FILE_SOURCE_ID = M.MBR_CD
AND M.MBR_ID LIKE '%' || #{detailSearch.mbrId} || '%'
AND M.MBR_NM LIKE '%' || #{detailSearch.mbrNm} || '%'
AND M.MBR_CD = #{detailSearch.mbrCd}
AND 1=0
AND B.AUTH_APPR_YN = #{detailSearch.authApprYn}
AND F_B.FILE_ID IS NOT NULL
AND F_B.FILE_ID IS NULL
UNION ALL
SELECT M.MBR_CD M_MBR_CD , M.MBR_ID , M.MBR_PW , M.MBR_NM , M.MBR_NNM , M.MBR_TELNO , M.MBR_EML_ADDR , M.MBR_BASIC_ADDR , M.MBR_DETAIL_ADDR , M.MBR_PROFIL_IMAGE , M.MBR_FRST_REG_DT , M.MBR_STATUS_CODE , M.MBR_DELETE_DATE , M.MBR_ZIP , NULL AS B_MBR_CD , NULL AS BROK_NM , NULL AS BROK_REG_NO , NULL AS CRTF_NO , NULL AS REPR_NM , NULL AS REPR_TEL_NO , NULL AS REG_DTM , NULL AS BROK_ADDR2 , NULL AS BROK_ADDR1 , NULL AS BROK_ZIP , NULL AS B_AUTH_APPR_YN , NULL AS B_AUTH_APPR_DT , T.RENTAL_PTY_ID , T.RENTAL_PTY_BIZ_REG_FILE_PATH , T.RENTAL_PTY_REG_BLDG_CNT , T.RENTAL_PTY_BIZ_REG_NO , T.RENTAL_PTY_FILE , T.RENTAL_PTY_FILE2 , T.LSR_YN_TYPE_CD , T.MBR_CD T_MBR_CD , T.LSR_TYPE_GROUP_CD , T.AUTH_APPR_YN T_AUTH_APPR_YN , T.AUTH_APPR_DT T_AUTH_APPR_DT , NULL AS B_FILE_ID , F_T.FILE_ID AS T_FILE_ID FROM MEMBER M INNER JOIN TENANCY T ON M.MBR_CD = T.MBR_CD LEFT OUTER JOIN FILES F_T ON F_T.FILE_SOURCE_REF = 'TENANCY' AND F_T.FILE_SOURCE_ID = M.MBR_CD
AND M.MBR_ID LIKE '%' || #{detailSearch.mbrId} || '%'
AND M.MBR_NM LIKE '%' || #{detailSearch.mbrNm} || '%'
AND M.MBR_CD = #{detailSearch.mbrCd}
AND 1=0
AND T.AUTH_APPR_YN = #{detailSearch.authApprYn}
AND F_T.FILE_ID IS NOT NULL
AND F_T.FILE_ID IS NULL
) ORDER BY CASE WHEN COALESCE(B_AUTH_APPR_YN, T_AUTH_APPR_YN) = 'Y' THEN 1 ELSE 0 END ASC, GREATEST(B_AUTH_APPR_DT, T_AUTH_APPR_DT) DESC, M_MBR_CD DESC ) A
WHERE ROWNUM <= #{lastRecordIndex} ) WHERE RNUM >= #{firstRecordIndex}
